<script>
(()=>{const origin=document.getElementById('originPort'),destination=document.getElementById('destinationPort');if(!origin||origin.dataset.ready)return;origin.dataset.ready='1';const selected=s=>s.options[s.selectedIndex];const slug=v=>(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z]/g,'').slice(0,3).toUpperCase();const refresh=()=>{const a=selected(origin),b=selected(destination),modality=a?.dataset.modality||b?.dataset.modality||'fluvial';document.getElementById('originCity').value=a?.dataset.city||'';document.getElementById('destinationCity').value=b?.dataset.city||'';document.getElementById('routeModality').value=modality;document.getElementById('routeModalityLabel').value=a?.value?(modality==='aereo'?'✈️ Aéreo':'🚤 Fluvial'):'Se completa con el origen';[...destination.options].forEach(o=>{o.disabled=!!o.value&&(o.value===a?.value||o.dataset.modality!==modality)});if(b?.disabled){destination.value='';}const currentDestination=selected(destination);document.getElementById('routeSummary').textContent=a?.value&&currentDestination?.value?`${a.dataset.city} → ${currentDestination.dataset.city} · ${modality==='aereo'?'Aéreo':'Fluvial'}`:'Selecciona origen y destino';const code=document.getElementById('routeCode');if(!code.value&&a?.dataset.city&&currentDestination?.dataset.city)code.value=`TRM-${slug(a.dataset.city)}-${slug(currentDestination.dataset.city)}`;};origin.addEventListener('change',refresh);destination.addEventListener('change',refresh);refresh();})();
</script>
